var RANKS=[["Cadet",0],["Pilot",100],["Specialist",250],["Commander",500],["Mission Director",900]];
var SPECS=["Pilot","Mission Specialist","Astrophysicist","Engineer","Planetary Geologist"];
var AVS=["👩‍🚀","🧑‍🚀","👨‍🚀","🛸","🪐","🌙"];
var PATCH=["#3de6ff","#ff4fd8","#ffb347","#5dffa3"];
var SHAPES=["●","⬟","◆","★"];
var LESSONS=[
{id:"orb",t:"Orbital mechanics: why satellites don’t fall",min:6,xp:20,sk:"nav",lv:"Cadet",body:"A satellite is always falling, but it moves sideways so fast that the ground curves away beneath it. The ISS circles Earth at about 7.7 km/s, once every 90 minutes.",q:"What keeps the ISS in orbit?",o:["No gravity up there","Sideways speed balancing gravity’s pull","Rocket engines firing constantly"],a:1},
{id:"rkt",t:"Rocket science: the rocket equation",min:8,xp:20,sk:"eng",lv:"Cadet",body:"Rockets push mass backward to go forward. The rocket equation shows that adding fuel needs even more fuel to carry it, which is why rockets are mostly propellant and use stages.",q:"Why do rockets use stages?",o:["To drop dead weight once fuel is spent","To look more impressive","To cool the engines"],a:0},
{id:"bh",t:"Black holes: beyond the horizon",min:7,xp:25,sk:"sci",lv:"Pilot",body:"A black hole is a region where gravity is so strong that nothing, not even light, can escape once it passes the event horizon. They form when massive stars collapse.",q:"What is the event horizon?",o:["The black hole’s surface of solid matter","The point of no return for light","A ring of fire around the hole"],a:1},
{id:"exo",t:"Exoplanets: finding other worlds",min:6,xp:25,sk:"sci",lv:"Pilot",body:"Astronomers find exoplanets by watching stars dim slightly as a planet crosses in front (the transit method). Thousands are confirmed, and some orbit in the habitable zone.",q:"What does the transit method detect?",o:["A tiny dip in starlight","Radio signals from aliens","Planet shadows on Earth"],a:0},
{id:"ls",t:"Life support: air, water, and waste",min:9,xp:30,sk:"eng",lv:"Specialist",body:"Space stations recycle most of their water, including humidity and urine, and make oxygen by splitting water with electricity. Every gram launched costs money, so closing the loop matters.",q:"How does the ISS make oxygen?",o:["Electrolysis of water","Growing forests","Shipping tanks every week"],a:0},
{id:"law",t:"Space law and ethics",min:7,xp:30,sk:"sci",lv:"Commander",body:"The 1967 Outer Space Treaty says no nation can claim the Moon or other bodies, and space should be used peacefully. New questions are emerging around mining, debris and planetary protection.",q:"Under the Outer Space Treaty, can a country own the Moon?",o:["Yes, if it plants a flag","No, celestial bodies can’t be claimed","Only the first to land"],a:1},
{id:"surv",t:"Surviving on Mars: power, water, food",min:8,xp:25,sk:"surv",lv:"Cadet",body:"A Mars base runs on three linked loops. Power comes from solar panels plus a small reactor, water is mined from underground ice, and food grows in greenhouses fed by recycled nutrients. Lose one loop and the others soon fail too.",q:"Why is solar power risky on Mars?",o:["Dust storms can block sunlight for weeks","The Sun does not shine there","Panels melt in the cold"],a:0}];
LESSONS.push(
{id:"astro-history",t:"A brief history of astronomy",min:7,xp:20,sk:"sci",cat:"Astronomy",lv:"Cadet",body:"People in many cultures mapped the sky to track seasons, navigate, and preserve stories. Telescopes transformed astronomy: Galileo observed moons orbiting Jupiter, while later astronomers used spectroscopy, photography, and space telescopes to study distant objects."},
{id:"constellations",t:"Constellations: patterns in the sky",min:5,xp:20,sk:"sci",cat:"Astronomy",lv:"Cadet",body:"A constellation is a named region of the sky, often associated with a pattern of stars as seen from Earth. Its stars can be at very different distances and usually are not physically connected. Astronomers use the official constellation regions to locate objects in the sky."},
{id:"stars",t:"How stars are born and change",min:7,xp:25,sk:"sci",cat:"Astronomy",lv:"Pilot",body:"Stars form when gravity draws gas and dust in a nebula together until the center becomes hot and dense enough for nuclear fusion. A star's mass shapes its life: Sun-like stars swell into red giants and leave white dwarfs, while massive stars can explode as supernovae and leave neutron stars or black holes."},
{id:"galaxies",t:"Galaxies and the Milky Way",min:6,xp:25,sk:"sci",cat:"Astronomy",lv:"Pilot",body:"A galaxy is a vast system of stars, gas, dust, and dark matter held together by gravity. Our Solar System lies in the Milky Way, a barred spiral galaxy containing hundreds of billions of stars. The Milky Way is one of many galaxies in the observable universe."},
{id:"moon-phases",t:"Why the Moon has phases",min:5,xp:20,sk:"nav",cat:"Astronomy",lv:"Cadet",body:"The Moon reflects sunlight, and half of its surface is illuminated at any moment. As it orbits Earth, we see different portions of that sunlit half, creating phases from new Moon to full Moon and back. Earth's shadow causes a lunar eclipse only when the Sun, Earth, and Moon line up closely."},
{id:"distance-stars",t:"Measuring distance to the stars",min:6,xp:25,sk:"nav",cat:"Astronomy",lv:"Pilot",body:"Astronomers measure nearby stellar distances with parallax: as Earth orbits the Sun, a nearby star appears to shift against more distant stars. Farther away, astronomers use objects with known brightness and redshift patterns. A light-year is a distance—the path light travels in one year—not a unit of time."},
{id:"gravity",t:"Gravity and free fall in orbit",min:6,xp:20,sk:"eng",cat:"Science",lv:"Cadet",body:"Gravity reaches the International Space Station; it is still strong at orbital altitude. The station and everything inside it are continually falling around Earth together, which creates the feeling of weightlessness. Its sideways speed keeps it missing the ground as it falls."},
{id:"spectra",t:"Reading starlight: spectra",min:6,xp:25,sk:"sci",cat:"Science",lv:"Pilot",body:"A prism or spectrograph spreads light into a spectrum. Atoms and molecules absorb or emit particular wavelengths, leaving patterns that act like fingerprints. By studying those patterns, astronomers can infer a star's composition, temperature, motion, and some properties of its atmosphere."},
{id:"microgravity",t:"The human body in microgravity",min:6,xp:20,sk:"surv",cat:"Science",lv:"Cadet",body:"In microgravity, fluids shift toward the head and muscles work differently because the body no longer supports its weight in the usual way. Without regular loading, bones and muscles can weaken. Astronauts exercise during missions and follow health checks to reduce these effects."},
{id:"astrobiology",t:"Astrobiology and the search for life",min:7,xp:25,sk:"sci",cat:"Science",lv:"Pilot",body:"Astrobiology studies how life begins, survives, and might be detected beyond Earth. Scientists look for environments with liquid water, useful chemistry, and energy, then search for possible biosignatures. A promising signal needs careful checking because nonliving processes can sometimes imitate signs of life."},
{id:"radiation",t:"Radiation beyond Earth's protection",min:6,xp:25,sk:"surv",cat:"Science",lv:"Pilot",body:"Earth's atmosphere and magnetic field shield the surface from much harmful space radiation. Crews beyond that protection can encounter energetic particles from the Sun and cosmic rays. Mission planners monitor space weather, limit exposure, and design habitats with shielding and safe areas."},
{id:"ecosystems",t:"Building a closed-loop space habitat",min:7,xp:25,sk:"eng",cat:"Science",lv:"Specialist",body:"A space habitat must manage air, water, food, and waste with limited resupply. Plants can help produce food and recycle carbon dioxide, while filters and recovery systems reclaim water and clean air. These loops reduce waste, but still need energy, maintenance, and backup systems."}
);
LESSONS.push(
{id:"entanglement",t:"Quantum entanglement",min:7,xp:25,sk:"sci",cat:"Physics",lv:"Pilot",body:"Entanglement is a quantum connection between systems. When entangled particles are measured, their results can be correlated more strongly than any classical theory based on pre-arranged local instructions can explain.",details:[["A shared quantum state","Imagine two particles prepared together and then carried far apart. Quantum physics describes them with one shared state, rather than giving each particle its own complete, independent set of properties. The particles are not sending signals to one another during a measurement; the unusual relationship is already part of how the pair was prepared."],["What a measurement reveals","A measurement asks a specific question about a particle, such as whether its spin points along a chosen direction. The result is a definite, ordinary observation. Before measurement, quantum theory generally predicts probabilities for possible outcomes, rather than saying that every answer was simply hidden and waiting to be uncovered."],["Correlations across distance","If two observers measure corresponding properties of entangled particles, their results are correlated. Changing the measurement direction changes the pattern. Repeating the experiment many times reveals statistical relationships that are stronger than classical local models allow, even when the particles are separated."],["Bell tests","Physicist John Bell showed how to compare quantum predictions with a broad family of theories in which each particle carries local, pre-set answers. Experiments test inequalities that those theories must obey. Observed violations agree with quantum mechanics and rule out that family of local hidden-variable explanations; they do not prove that every imaginable alternative is impossible."],["No faster-than-light messaging","The measurement results are correlated, but each observer sees a random-looking result on their own. Neither observer can choose an outcome to encode a message. They must later compare records through an ordinary communication channel, so entanglement cannot be used to send information faster than light."],["How scientists create it","Researchers can entangle photons, atoms, ions, and other quantum systems using carefully controlled interactions. They then measure the systems in different settings and compare many trials. Noise, imperfect detectors, and unwanted interactions can weaken the correlations, so experiments must control and account for these effects."],["Why it matters","Entanglement is being explored as a resource for quantum computing, quantum networks, secure communication protocols, and precision measurements. A useful device must create the desired shared states, manipulate them reliably, and protect them from environmental noise; entanglement by itself is not a finished technology."],["Key terms","A qubit is a quantum information unit. A correlation is a statistical relationship between observations. A Bell inequality is a mathematical limit on correlations predicted by local hidden-variable models. A quantum state is the mathematical description used to predict the outcomes of measurements."]],source:{label:"NIST: Quantum information and entanglement",url:"https://www.nist.gov/pml/time-and-frequency-division/quantum-information-sensing-and-networking"}},
{id:"superconductivity",t:"Superconductivity",min:7,xp:25,sk:"eng",cat:"Physics",lv:"Pilot",body:"Some materials become superconductors below a critical temperature, carrying direct current with zero electrical resistance.",details:[["What changes","Below a material's critical temperature, its electrical resistance vanishes and it expels magnetic fields (the Meissner effect). The superconducting state can be disrupted if temperature, magnetic field, or current exceeds a critical limit."],["How it is used","Superconducting wire can carry large currents and create powerful magnets. These magnets are used in MRI scanners and in particle accelerators."],["Current limits","Many superconductors need substantial cooling. Some newer materials work at higher temperatures than early superconductors, but still require cooling; the mechanisms in several high-temperature materials remain an active research question."]],source:{label:"U.S. Department of Energy: Superconductivity",url:"https://www.energy.gov/science/doe-explainssuperconductivity"}},
{id:"gravitational-waves",t:"Gravitational waves",min:8,xp:30,sk:"sci",cat:"Physics",lv:"Specialist",body:"Gravitational waves are traveling ripples in spacetime produced by accelerating masses, especially compact objects such as black holes and neutron stars orbiting and merging.",details:[["What they are","In general relativity, changing distributions of mass and energy can create disturbances in spacetime that travel outward at the speed of light. By the time a wave reaches Earth, its stretching and squeezing effect is extraordinarily small."],["How we detect them","LIGO uses laser interferometers with long perpendicular arms. A passing wave changes the relative arm lengths by a tiny amount, shifting the interference pattern of laser light. Scientists compare the signal with models and data from other observatories."],["What a signal tells us","A merging binary produces a characteristic rising signal called a chirp as the objects orbit faster and finally merge. The waveform helps researchers estimate the objects' masses, spins, and distance, and test gravity in extreme conditions."],["Why it matters","The first direct detection, GW150914, came from two merging black holes and was announced in 2016. Gravitational-wave astronomy lets scientists observe violent events that may be difficult to study with light alone. The signal is a measured distortion of spacetime, not sound."]],source:{label:"LIGO: What are gravitational waves?",url:"https://www.ligo.caltech.edu/LA/page/what-are-gw"}},
{id:"thermodynamics",t:"Thermodynamics",min:8,xp:25,sk:"eng",cat:"Physics",lv:"Pilot",body:"Thermodynamics studies heat, work, temperature, and energy, and explains how energy moves and changes form.",details:[["Core idea","A system's internal energy changes when energy enters or leaves as heat or work. Energy is conserved: it changes form or moves between a system and its surroundings rather than appearing from nothing."],["Entropy and direction","The second law says that the total entropy of an isolated system does not decrease. In everyday terms, heat naturally spreads from warmer objects to cooler ones, and real energy transfers make some energy less available to do useful work."],["Thermal equilibrium","The zeroth law describes how systems in thermal equilibrium share the same temperature; it gives the basis for thermometers. The third law describes the behavior of entropy as temperature approaches absolute zero, which cannot be reached by a finite sequence of ordinary processes."],["Why it matters in space","Spacecraft and habitats must control where heat goes. Insulation, radiators, heaters, and thermal coatings help protect instruments and crews through sunlight and shadow."]],source:{label:"NASA: Thermal energy and thermodynamics lesson",url:"https://www.nasa.gov/wp-content/uploads/2024/01/nasa-lp-feel-the-heat.pdf"}},
{id:"dark-matter",t:"Dark matter",min:7,xp:30,sk:"sci",cat:"Physics",lv:"Specialist",body:"Dark matter is the name for unseen matter inferred from its gravitational effects on stars, galaxies, and light.",details:[["Why scientists infer it","Stars in galaxies move in ways that indicate more gravitational mass than the visible stars and gas can explain. Gravitational lensing and observations of galaxy clusters provide additional evidence for unseen mass."],["What it is not","Dark matter does not emit, absorb, or reflect enough light for telescopes to see it directly. It is different from dark energy, the name for the unknown cause of the universe's accelerated expansion."],["What remains unknown","Its particle or physical nature has not been identified. Experiments search for possible particles and astrophysical observations map its gravitational influence, but no candidate has yet been confirmed as dark matter."]],source:{label:"NASA Science: Dark matter",url:"https://science.nasa.gov/dark-matter/"}},
{id:"string-theory",t:"String theory",min:8,xp:30,sk:"sci",cat:"Physics",lv:"Commander",body:"String theory is a theoretical framework in which fundamental ingredients are one-dimensional strings rather than point-like particles.",details:[["The basic proposal","Different vibration patterns of a string would appear as different particles with different properties. Some versions contain a vibration with properties associated with a graviton, a hypothetical quantum of gravity."],["What it tries to address","Researchers study string theory as a possible mathematical framework for connecting quantum physics with gravity and for describing fundamental interactions within a broader structure."],["Scientific status","String theory has generated useful mathematical ideas, but it has not been experimentally confirmed as the description of nature. Its possible predictions are difficult to test, so it should be understood as an active theoretical research program, not an established discovery."]],source:{label:"CERN: Research overview on particle physics from string theory",url:"https://cds.cern.ch/record/2806195/files/2204.01742.pdf"}},
{id:"quantum-computing",t:"Quantum computing",min:8,xp:30,sk:"eng",cat:"Physics",lv:"Specialist",body:"Quantum computers process information using qubits and controlled quantum effects such as superposition and entanglement.",details:[["Qubits and operations","A classical bit is 0 or 1. A qubit can be prepared in a quantum superposition, and gates change its state. Entangling multiple qubits lets a program represent correlations that classical bits cannot capture in the same way."],["How a result is obtained","A quantum program uses interference to increase the chance of useful outcomes, then measurements produce ordinary classical data. A quantum computer does not simply try every answer at once; algorithms must be designed so the desired answer can be extracted."],["Challenges and uses","Qubits are easily disturbed by heat, noise, or stray fields, so errors and error correction are major challenges. Researchers explore applications in simulating quantum materials and chemistry, optimization, and other specialized problems; quantum computers are not faster for every task."]],source:{label:"NIST: Quantum computing explained",url:"https://www.nist.gov/quantum-information-science/quantum-computing-explained"}},
{id:"astrophysics",t:"Astrophysics",min:7,xp:25,sk:"sci",cat:"Physics",lv:"Pilot",body:"Astrophysics applies physics to explain how stars, planets, galaxies, black holes, and the universe behave and evolve.",details:[["What astrophysicists study","Questions include how stars form and change, how planets and galaxies evolve, how matter behaves near black holes, and how the universe began and changes over time."],["How we investigate","Telescopes collect light across radio, infrared, visible, ultraviolet, X-ray, and gamma-ray wavelengths. Spectra, brightness changes, motion, and gravitational-wave signals help researchers infer the physical conditions of objects too distant to visit."],["Why it matters","By connecting observations to physical laws, astrophysics turns measurements of distant objects into evidence about the history, composition, and workings of the cosmos."]],source:{label:"NASA: Astrophysics",url:"https://science.nasa.gov/astrophysics/"}},
{id:"neutrino-physics",t:"Neutrino physics",min:7,xp:25,sk:"sci",cat:"Physics",lv:"Pilot",body:"Neutrinos are electrically neutral, extremely light particles that interact so weakly with matter that they can pass through planets with little chance of stopping.",details:[["Three flavors","Neutrinos are produced as electron, muon, and tau neutrinos. Experiments have shown that neutrinos can change flavor while traveling, a phenomenon called neutrino oscillation that means they have nonzero mass."],["Where they come from","Neutrinos are produced in the Sun, Earth's atmosphere, nuclear reactors, supernovae, and particle accelerators. Their weak interactions make them difficult to detect, so experiments use carefully designed detectors and large amounts of target material."],["What scientists learn","Measuring neutrino energies, flavors, and interactions can test the Standard Model and reveal details about the Sun, exploding stars, and particle processes that are hard to study in other ways."]],source:{label:"CERN: Neutrino research",url:"https://home.cern/science/experiments/cern-neutrino-platform/"}}
);
var ASTRO_TOPICS=[
["astrophysics","Astrophysics","Physics of cosmos","Astrophysics applies physics to understand stars, galaxies, planets, and the universe.","Astronomers combine observations across the electromagnetic spectrum with physical models to estimate temperature, composition, mass, motion, and distance."],
["extragalactic-astronomy","Extragalactic astronomy","Beyond Milky Way","Extragalactic astronomy studies objects and structures outside the Milky Way.","Researchers observe other galaxies, galaxy groups, quasars, and the cosmic web. Their light can take millions or billions of years to reach us, so distant observations also reveal earlier eras of the universe."],
["planetary-science","Planetary science","Planets and moons","Planetary science investigates planets, moons, dwarf planets, rings, asteroids, and comets.","Scientists combine spacecraft measurements, telescopic observations, laboratory experiments, and models to study surfaces, interiors, atmospheres, magnetic fields, and planetary history."],
["galactic-astronomy","Galactic astronomy","Galaxy structure study","Galactic astronomy examines the structure, contents, and evolution of galaxies, including our own.","Astronomers map stars, gas, dust, and dark matter by measuring their light and motion. Comparing many galaxies helps show how they grow, form stars, and interact."],
["solar-physics","Solar physics","Sun's physical study","Solar physics studies the Sun's interior, atmosphere, magnetic fields, and changing activity.","Telescopes observe the Sun in different wavelengths, while spacecraft measure particles and magnetic fields nearby. These observations help explain sunspots, flares, and space weather."],
["astrobiology","Astrobiology","Life in universe","Astrobiology studies how life begins, survives, and might be detected beyond Earth.","Researchers examine habitable environments, chemistry, water, and energy sources. A possible biosignature must be checked carefully because nonliving processes can sometimes imitate signs of life."],
["astrophysical-plasma","Astrophysical plasma","Space plasma physics","Astrophysical plasma is hot, electrically charged gas found in stars, nebulae, and space between galaxies.","Because plasma contains charged particles, magnetic fields can shape its motion and energy. Scientists study it with telescopes, spacecraft, and laboratory experiments."],
["radio-astronomy","Radio astronomy","Radio wave observation","Radio astronomy observes natural radio waves from objects and processes in space.","Radio dishes and arrays measure signals from sources such as pulsars, gas clouds, galaxies, and the cosmic microwave background. Combining multiple antennas can create very detailed maps."],
["visible-light-astronomy","Visible-light astronomy","Visible light study","Visible-light astronomy studies the wavelengths human eyes can see, from red through violet.","Optical telescopes collect and focus this light. Images show shapes and brightness, while spectra reveal clues about an object's temperature, composition, and motion."],
["astrometry","Astrometry","Celestial position measurement","Astrometry precisely measures the positions and motions of stars and other celestial objects.","Repeated measurements reveal parallax, proper motion, and tiny changes caused by orbiting companions. These data help map the Milky Way and measure distances."],
["infrared-astronomy","Infrared astronomy","Infrared sky study","Infrared astronomy observes wavelengths longer than visible red light.","Infrared telescopes can study cool objects and see through some cosmic dust. Space observatories avoid much of the infrared absorption caused by Earth's atmosphere and water vapor."],
["ultraviolet-astronomy","Ultraviolet astronomy","UV spectrum study","Ultraviolet astronomy studies energetic light just beyond violet in the electromagnetic spectrum.","Hot stars, stellar atmospheres, and energetic gas emit ultraviolet light. Earth's atmosphere blocks most ultraviolet wavelengths, so many observations are made from space."],
["x-ray-astronomy","X-ray astronomy","X-ray sky study","X-ray astronomy observes high-energy radiation from some of the most extreme cosmic environments.","Black holes, neutron stars, hot gas, and stellar explosions can produce X-rays. Since Earth's atmosphere absorbs them, X-ray telescopes operate above the atmosphere."],
["neutrino-astronomy","Neutrino astronomy","Neutrino detection science","Neutrino astronomy uses nearly massless, electrically neutral particles to study cosmic events.","Neutrinos pass through most matter, carrying information from dense regions that light may not escape. Huge detectors watch for the rare interactions that reveal their arrival."],
["astrochemistry","Astrochemistry","Space chemical study","Astrochemistry studies the molecules and chemical reactions found in space.","Spectral fingerprints in starlight and radio signals identify atoms and molecules in clouds, disks, and planetary atmospheres. Laboratory measurements help interpret those fingerprints."],
["gamma-ray-astronomy","Gamma-ray astronomy","Gamma ray detection","Gamma-ray astronomy explores the highest-energy light in the universe.","Gamma rays can come from pulsars, black holes, supernova remnants, and powerful cosmic explosions. Space telescopes detect them because Earth's atmosphere blocks this radiation."],
["spectroscopy","Spectroscopy","Light spectrum analysis","Spectroscopy separates light into wavelengths and studies the patterns within it.","Atoms and molecules leave characteristic spectral lines. Their positions and strengths can reveal an object's composition, temperature, density, rotation, and motion."],
["eclipse","Eclipse","Celestial shadow event","An eclipse happens when one celestial body moves into the shadow of another or blocks its light from a viewer.","The Sun, Earth, and Moon must align closely for a solar or lunar eclipse. Eclipses let scientists study the Sun's outer atmosphere and refine measurements of celestial orbits."],
["orb","Orbit","Path around body","An orbit is the curved path one object follows around another under gravity.","An orbit's shape, speed, and orientation depend on the objects' motion and gravitational pull. Satellites stay in orbit by moving sideways fast enough to keep falling around Earth."],
["milky-way","Milky Way","Our home galaxy","The Milky Way is the barred spiral galaxy that contains our Solar System.","From inside the galaxy, astronomers map its stars, gas, and dust using many wavelengths. Dust hides parts of the visible view, so infrared and radio observations help reveal its structure."],
["solar-flare","Solar flare","Sudden Sun eruption","A solar flare is a sudden release of energy from the Sun's atmosphere, often near magnetically active regions.","Flares brighten the Sun in X-rays and ultraviolet light and can affect radio communication near Earth. They are related to, but not the same as, coronal mass ejections."],
["redshift","Redshift","Light wavelength shift","Redshift means light is observed at longer wavelengths than when it was emitted.","The shift can reveal motion away from us, and cosmological redshift occurs as space expands while light travels. Astronomers measure spectral lines to calculate the shift."],
["sunspot","Sunspot","Dark solar region","Sunspots are cooler, darker-looking regions on the Sun's visible surface associated with strong magnetic fields.","Their number changes over an approximately 11-year cycle. Twisted magnetic fields around active regions can also be linked to flares and other solar activity."],
["asteroid-belt","Asteroid belt","Rocky space region","The main asteroid belt is a broad region of rocky bodies between the orbits of Mars and Jupiter.","Jupiter's gravity helped prevent material there from combining into a planet. Asteroids vary from small fragments to dwarf planets such as Ceres."],
["kuiper-belt","Kuiper belt","Distant icy region","The Kuiper Belt is a disk-shaped region of icy bodies beyond Neptune.","It contains dwarf planets and many smaller objects left from the Solar System's formation. Neptune's gravity shapes many of their orbits, and some become short-period comets."],
["exo","Exoplanet","Planet beyond Sun","An exoplanet is a planet that orbits a star beyond our Sun.","The transit method looks for a small, repeating dip in a star's brightness; other methods track a star's wobble or directly image a planet. Follow-up observations can estimate a world's size, orbit, and atmosphere."],
["hot-jupiter","Hot Jupiter","Close giant planet","A hot Jupiter is a gas-giant exoplanet that orbits very close to its star.","Their short orbital periods make many easy to detect with the transit method. Their intense heat and unusual atmospheres help scientists test models of how planets form and migrate."],
["oort-cloud","Oort cloud","Comet reservoir zone","The Oort Cloud is a hypothesized distant shell of icy bodies surrounding the Solar System.","It has not been directly imaged; its existence is inferred partly from the paths of long-period comets. Passing stars and the Milky Way's gravity can disturb objects and send some toward the Sun."],
["super-earth","Super-Earth","Massive rocky planet","A super-Earth is an exoplanet larger or more massive than Earth but smaller than Neptune.","The name describes a size range, not an Earth-like environment. These worlds may be rocky, rich in water, or have thick gas envelopes; observations are needed to learn more."],
["rogue-planet","Rogue planet","Starless wanderer","A rogue planet travels through space without orbiting a star.","Some may have been ejected from their original planetary systems, while others may form alone. Astronomers can search for them through gravitational microlensing or faint infrared glow."],
["supernova","Supernova","Exploding massive star","A supernova is a powerful stellar explosion marking the end of some stars' lives.","A massive star can collapse when its core can no longer support itself, while some white dwarfs explode after gaining material or merging. Supernovae spread elements and leave expanding remnants."],
["bh","Black hole","Gravity trap object","A black hole is a region where gravity is so strong that nothing can escape from inside its event horizon.","Astronomers infer black holes from nearby stars and gas, image glowing material around some, and detect mergers through gravitational waves. The black hole itself emits no light."],
["constellations","Constellation","Star pattern group","A constellation is one of the officially defined regions of the sky, many named after patterns of stars.","The stars in a constellation may be at very different distances and are not usually physically connected. Constellation boundaries give astronomers a standard way to describe sky locations."],
["neutron-star","Neutron star","Dense stellar remnant","A neutron star is the extremely dense core left behind by some massive stars after a supernova.","It can contain more mass than the Sun compressed into a sphere about the size of a city. Rapidly spinning neutron stars with beams of radiation are observed as pulsars."],
["event-horizon","Event horizon","Point of no return","An event horizon is the boundary around a black hole beyond which escape to the outside is impossible.","It is not a solid surface. Its size depends on the black hole's mass, and material outside it can still emit light before crossing the boundary."],
["orion-nebula","Orion Nebula","Bright star nursery","The Orion Nebula is a nearby region of gas and dust where stars are forming.","Young stars heat and illuminate the surrounding cloud. Observations across visible and infrared light reveal both the bright surface and young objects hidden within dust."],
["pleiades","Pleiades","Seven star cluster","The Pleiades, also called the Seven Sisters, is a young open cluster of stars in Taurus.","Its stars formed from the same cloud and are loosely bound by gravity. The cluster is easy to see with the naked eye, while telescopes reveal many more members and surrounding dust."],
["magellanic-clouds","Magellanic Clouds","Satellite galaxies","The Large and Small Magellanic Clouds are nearby dwarf galaxies that accompany the Milky Way.","Their closeness lets astronomers study star formation and stellar evolution in detail. Their gravity also affects the gas and structure of the Milky Way's surroundings."],
["dark-matter","Dark matter","Invisible mass concept","Dark matter is unseen matter inferred from its gravitational influence on stars, galaxies, and light.","Galaxy motions and gravitational lensing provide evidence for extra mass that does not emit or absorb light in the usual way. Its physical nature remains unknown, and it is not the same as dark energy."],
["andromeda-galaxy","Andromeda Galaxy","Nearest spiral galaxy","The Andromeda Galaxy is a large spiral galaxy and the nearest major galaxy to the Milky Way.","It is visible to the unaided eye from a dark location. Measurements of its stars and motion help astronomers compare the structure and history of neighboring galaxies."],
["big-bang","Big Bang","Universe origin theory","The Big Bang model describes the universe expanding from an earlier hot, dense state about 13.8 billion years ago.","Evidence includes the expansion of the universe, the cosmic microwave background, and the observed abundance of light elements. The model describes early cosmic evolution, not an explosion into empty space."],
["olbers-paradox","Olbers' paradox","Night sky brightness","Olbers' paradox asks why the night sky is dark if an infinite, eternal universe filled uniformly with stars should make every direction bright.","The modern explanation includes the universe's finite age and expansion: light from very distant stars has not had unlimited time to arrive, and expansion stretches its wavelengths. The simple paradox assumes conditions that our universe does not meet."],
["stars","Stellar astronomy","Star lifecycle study","Stellar astronomy studies how stars form, shine, change, and end their lives.","A star's mass strongly shapes its evolution. Astronomers use brightness, color, spectra, and clusters of stars to test models of stellar structure and lifecycles."],
["relativistic-astrophysics","Relativistic astrophysics","Relativity in space","Relativistic astrophysics applies Einstein's theories to objects and events involving strong gravity or speeds near light speed.","It is used to model black holes, neutron stars, gravitational waves, and jets from active galaxies. Observations can test these predictions in environments that cannot be reproduced on Earth."],
["solar-system","Solar System","Our planetary system","The Solar System includes the Sun and the objects held in orbit by its gravity.","It contains eight planets, dwarf planets, moons, asteroids, comets, and distant icy populations. Studying their different surfaces and orbits helps reconstruct how the system formed."],
["high-energy-astrophysics","High-energy astrophysics","Energetic cosmic events","High-energy astrophysics studies energetic particles and radiation from extreme cosmic environments.","X-ray and gamma-ray observatories investigate black holes, neutron stars, supernova remnants, and cosmic explosions. These observations trace matter heated and accelerated to extreme conditions."],
["cosmic-ray-astronomy","Cosmic ray astronomy","Cosmic particle study","Cosmic rays are energetic particles that arrive from space, including protons and atomic nuclei.","Magnetic fields bend their paths, so their arrival directions do not always point straight back to their sources. Detectors on Earth and in space measure their energies and particle types."],
["hubble-constant","Hubble constant","Expansion rate measure","The Hubble constant describes the present-day rate at which the expanding universe increases distances between faraway galaxies.","Astronomers estimate it using several methods, including distance measurements and observations of the early universe. Different methods have produced values that do not fully agree, an active research question called the Hubble tension."]
];
var ASTRO_EXPANSIONS={
"astrophysics":["It connects observations to physical laws such as gravity, nuclear physics, and radiation, turning distant light into evidence about how the cosmos works.","Spectra can reveal the elements in an object, while brightness and motion help estimate its size, distance, and mass. Models are compared with new observations and revised when they do not fit."],
"extragalactic-astronomy":["The field spans nearby dwarf galaxies as well as extremely distant galaxies and active galactic nuclei. Looking farther away also means looking further back in cosmic time.","Different wavelengths reveal different components, from hot gas and young stars to older stellar populations. Large surveys compare galaxy shapes, colors, and distances to trace how cosmic structure developed."],
"planetary-science":["The field includes worlds in our Solar System and planets around other stars. Comparing them helps explain why planets that formed from similar disks can end up with very different surfaces and atmospheres.","Spacecraft can map terrain, sample local environments, and measure magnetic fields; telescopes study distant worlds without visiting them. Craters, minerals, and atmospheric chemistry preserve clues to a planet's past."],
"galactic-astronomy":["A galaxy is a gravitational system with stars, gas, dust, and dark matter, often arranged in a disk, central bulge, and extended halo. Galaxies can also change through collisions and close encounters.","Astronomers combine position, color, and velocity measurements to separate stellar populations and map their orbits. This reveals where stars formed and how the galaxy assembled over time."],
"solar-physics":["The Sun's magnetic field is generated by moving electrically conducting plasma inside it. Changes in that field drive much of the Sun's visible activity and influence the space environment around Earth.","Solar observatories track surface features, magnetic fields, and emissions from the corona. Spacecraft near the Sun sample particles and fields directly, helping connect solar eruptions to their effects in space."],
"astrobiology":["It includes the study of life on Earth in extreme environments, the chemistry of potential habitats, and the search for signs of life elsewhere. A habitable environment is not proof that life is present.","Robotic missions analyze rocks, soils, and atmospheres, while telescopes examine exoplanet atmospheres for combinations of gases. Researchers compare possible biological signals against nonliving explanations before drawing conclusions."],
"astrophysical-plasma":["Plasma contains free electrons and ions, so it responds strongly to electric and magnetic fields. It is common in space even though ordinary matter on Earth is usually solid, liquid, or neutral gas.","Spectral observations show plasma temperature and composition, while spacecraft measure local particles and fields. Computer models help explain phenomena such as stellar winds, glowing nebulae, and jets from compact objects."],
"radio-astronomy":["Radio waves have long wavelengths and can pass through some clouds of cosmic dust that block visible light. They reveal cold gas and energetic processes that may be faint or invisible in optical images.","Arrays combine signals from separated dishes to act like a much larger telescope, improving detail. Radio observations can map hydrogen gas, time pulsar signals, and measure the afterglow of energetic events."],
"visible-light-astronomy":["Visible light is only a small part of the electromagnetic spectrum, but it provides detailed images of stars, planets, nebulae, and galaxies. Earth's atmosphere allows much visible light through, making ground-based observatories useful.","Cameras record brightness and shape, and spectrographs spread light into its component wavelengths. Adaptive optics and space telescopes help reduce blur caused by Earth's atmosphere."],
"astrometry":["A star's apparent shift over the year is called parallax and gives a geometric distance measurement. Accurate positions also reveal how objects move across the sky and can expose the gravitational pull of unseen companions.","Space missions such as Gaia measure positions for enormous numbers of stars with high precision. Combining position, parallax, and motion produces three-dimensional maps of our galaxy."],
"infrared-astronomy":["Infrared observations are especially useful for cool objects and young stars hidden inside dusty clouds. Expanding space also stretches light from very distant early galaxies into infrared wavelengths.","Detectors must often be cooled so their own heat does not overwhelm faint signals. Space telescopes such as Webb observe infrared light above much of the atmosphere's absorption."],
"ultraviolet-astronomy":["Ultraviolet light is emitted strongly by very hot stars, active galaxies, and gas heated to high temperatures. It can expose processes that are difficult to see in visible light alone.","Because the atmosphere absorbs most ultraviolet wavelengths, observatories need to operate above it. Researchers use ultraviolet spectra to measure hot gas, stellar winds, and the formation of young stars."],
"x-ray-astronomy":["X-rays are produced by extremely hot gas and by matter accelerated near compact objects. Their energy can reveal violent activity around black holes, neutron stars, and supernova remnants.","Earth's atmosphere blocks cosmic X-rays, so detectors fly on satellites. Instruments record each photon's energy and arrival time to build images and study how sources change."],
"neutrino-astronomy":["Unlike light, neutrinos can escape from dense cosmic interiors with little interaction, carrying information from otherwise hidden regions. Their weak interaction also makes them exceptionally difficult to catch.","Large detectors use water, ice, or other materials to spot the faint flashes or tracks created when a neutrino rarely interacts. Matching detections with telescopes can identify the kind of cosmic source that produced them."],
"astrochemistry":["Space chemistry includes simple molecules such as water and carbon monoxide as well as more complex carbon-bearing molecules. Reactions can occur in thin gas or on the icy surfaces of dust grains.","Each molecule has characteristic spectral lines, often measured with radio or infrared telescopes. Laboratory experiments reproduce low-temperature conditions so astronomers can identify signals and model chemical pathways."],
"gamma-ray-astronomy":["Gamma rays carry more energy per photon than any other part of the electromagnetic spectrum. They are associated with particle acceleration, radioactive decay, and some of the universe's most energetic explosions.","Space detectors measure gamma-ray energies and arrival directions, while some ground-based observatories detect particle showers created when gamma rays hit the atmosphere. Coordinated observations help locate fast, brief bursts."],
"spectroscopy":["Spectral lines form when atoms and molecules absorb or emit particular wavelengths. Their patterns act like fingerprints, but line strength and shape also depend on temperature, pressure, and motion.","Astronomers compare observed spectra with laboratory measurements and physical models. A shift in the lines can show whether an object is moving toward or away from us, while broadening can reveal rotation or turbulence."],
"eclipse":["A solar eclipse occurs when the Moon passes between Earth and the Sun; a lunar eclipse occurs when the Moon passes through Earth's shadow. The alignment must be close, so eclipses do not happen every month.","During totality in a solar eclipse, the bright solar disk is covered and the corona becomes easier to observe. Safe viewing equipment is essential for every partial phase of a solar eclipse."],
"orb":["Most bound orbits are elliptical, with the central body at one focus; circular orbits are a special case. Orbital speed changes along an ellipse, with an object moving fastest when closest to the body it orbits.","Repeated position measurements let scientists calculate orbital elements and predict future locations. The same mechanics guides satellite placement, spacecraft transfers, and estimates of binary-star masses."],
"milky-way":["The Milky Way has a central bar, spiral arms, a disk, and a surrounding halo. Our Sun is in the disk, far from the galactic center, and takes hundreds of millions of years to complete one orbit around it.","Dust obscures much of the central region in visible light, so infrared and radio surveys are important. Star motions, gas maps, and observations of globular clusters help trace the galaxy's shape and history."],
"solar-flare":["Flares occur when magnetic energy in the solar atmosphere is rapidly released, heating particles and producing radiation across many wavelengths. They often happen in active regions where magnetic fields are complex.","Satellites monitor flare brightness in X-rays and ultraviolet light and provide warnings of intense solar activity. Strong events can disrupt radio communication and affect spacecraft systems, though effects depend on the event and Earth's magnetic environment."],
"redshift":["For nearby objects, motion away from an observer can stretch observed wavelengths; motion toward us shifts them toward blue. On cosmic scales, expansion stretches light as it travels through space.","Astronomers identify known spectral lines and measure how far they have shifted. Redshift helps estimate recession and distance for distant galaxies, but interpreting it requires a model of the universe's expansion."],
"sunspot":["Sunspots have a darker central umbra and a lighter surrounding penumbra. They look dark because they are cooler than the surrounding solar surface, not because they are cold.","Solar telescopes track their number, size, and magnetic structure over time. Their changing abundance marks the Sun's activity cycle, and complex sunspot groups can be sites of flares."],
"asteroid-belt":["The main belt is not a crowded field of rocks; most asteroids are separated by large distances. Its objects preserve material from the early Solar System that never became part of a planet.","Telescopes measure their brightness and orbital paths, while spacecraft visit selected asteroids to study their surfaces directly. Composition and crater patterns help reconstruct how the belt evolved."],
"kuiper-belt":["The region includes Pluto and many smaller icy bodies, some in orbital patterns set by Neptune. These objects are remnants of planet formation and preserve information about the outer Solar System.","Most Kuiper Belt objects are faint and distant, so surveys repeatedly image wide areas of sky to find their slow motion. Their orbits and colors help distinguish different populations and histories."],
"exo":["Exoplanets range from small rocky worlds to gas giants and can orbit very close to their stars or far away. A planet's location in a so-called habitable zone does not by itself show that it has life or even surface water.","Transit observations can estimate a planet's size, while stellar wobble helps estimate its mass. Combining those measurements gives an approximate density; atmospheric spectra can then search for gases and clouds."],
"hot-jupiter":["Their close orbits expose them to intense starlight, giving many hot Jupiters very high atmospheric temperatures. Some are thought to have formed farther out and moved inward, though formation pathways can differ.","Frequent transits make their atmospheres practical to study as starlight passes through them. Measurements of heat distribution and atmospheric chemistry test models of weather on giant planets beyond our Solar System."],
"oort-cloud":["The proposed cloud is much farther away than the Kuiper Belt and may extend around the Solar System in all directions. It is a model-based population, not a region that astronomers have photographed directly.","Long-period comets arrive from a wide range of directions and provide clues to this distant reservoir. Gravitational nudges can alter an object's path and send it inward, where sunlight makes its icy surface active."],
"super-earth":["Super-Earth is a size and mass category, not a claim that the planet resembles Earth. Some may have solid surfaces, while others could have deep oceans or thick gaseous envelopes.","Transit measurements give radius and orbital period, and radial-velocity measurements estimate mass. Their combination helps estimate density, but atmosphere and surface conditions usually require additional observations and remain uncertain."],
"rogue-planet":["Without a nearby star, a rogue planet receives little starlight and may be extremely faint. Some could retain internal heat, and some may have been ejected from planetary systems during gravitational encounters.","Gravitational microlensing can reveal a planet when its gravity briefly magnifies a background star. Infrared surveys can also search for the faint heat from young or massive free-floating worlds."],
"supernova":["A supernova can briefly outshine its host galaxy and create an expanding cloud of hot debris. Different explosion pathways leave different chemical patterns and compact remnants.","Astronomers track how brightness and spectra change over time, then study the remnant at many wavelengths. These observations measure the elements thrown into space and help connect the explosion to its original star."],
"bh":["Black holes can form from collapsed massive stars or grow to millions or billions of solar masses in galactic centers. Hot gas around a black hole can shine brightly even though light cannot escape from inside the horizon.","Scientists study a black hole's effects on nearby matter, image the emission around some central black holes, and detect merging systems through gravitational waves. Multiple methods provide complementary evidence."],
"constellations":["Modern constellation boundaries divide the entire sky into 88 official regions. The familiar star pictures are useful guides, but perspective makes unrelated stars appear close together on the sky.","Star charts and sky apps use constellation regions to label where objects are found. Learning a few bright patterns can help observers orient themselves before searching for fainter targets."],
"neutron-star":["A neutron star packs stellar mass into a sphere only around the size of a city, making it one of the densest known kinds of matter. Its crust, magnetic field, and interior physics are unlike anything accessible in ordinary laboratories.","Pulsars are detected through regular pulses from rotating neutron stars whose beams sweep across Earth. X-ray timing and gravitational-wave observations can also probe their structure and behavior."],
"event-horizon":["For a non-rotating black hole, the horizon's radius is set by its mass; rotation changes the detailed geometry. Crossing the horizon is not like hitting a material wall, although tidal forces can be severe depending on the black hole.","The horizon itself cannot send light outward, so astronomers infer its presence from how nearby stars and gas behave. Images show glowing material and a dark central shadow, not a photograph of the horizon's surface."],
"orion-nebula":["The Orion Nebula is an emission nebula whose gas glows after being energized by hot young stars. It contains a stellar nursery where new stars and planetary systems are forming.","Visible-light images show glowing gas, while infrared observations peer through dust to reveal young stars. Studying this nearby region helps researchers compare star formation models with real systems."],
"pleiades":["The cluster's brightest blue-white stars formed relatively recently in astronomical terms and are still traveling together through space. The familiar name Seven Sisters reflects what many people can see without a telescope, though the cluster contains many more stars.","Astronomers compare the stars' positions, motions, brightness, and color to estimate the cluster's distance and age. The Pleiades also helps test models of how young star clusters change over time."],
"magellanic-clouds":["The Large and Small Magellanic Clouds are irregular dwarf galaxies visible from the Southern Hemisphere. They contain gas and active star-forming regions and orbit in the Milky Way's neighborhood.","Because they are relatively close, individual stars and nebulae can be studied in detail. Maps of their gas and stellar streams reveal how gravity has shaped their interactions with the Milky Way."],
"dark-matter":["Dark matter is inferred from gravity, not from a direct image of the matter itself. It appears to contribute much of the mass in galaxies and large-scale cosmic structures, but its identity is still unknown.","Evidence comes from galaxy rotation, gravitational lensing, and patterns in the cosmic microwave background. Experiments search for possible particles, while astronomical surveys map where the gravitational effects occur."],
"andromeda-galaxy":["Andromeda is a spiral galaxy with its own stars, gas, dust, and satellite galaxies. Its apparent size in the sky is large because it is one of our closest large galactic neighbors.","Astronomers resolve individual stars in some regions and measure the galaxy's rotation and distance. Comparing Andromeda with the Milky Way helps show how spiral galaxies vary and evolve."],
"big-bang":["The model describes the expansion and cooling of the universe from an early hot, dense state; it does not describe matter exploding from a central point into pre-existing space. The universe continues to expand today.","The cosmic microwave background is leftover radiation from an early stage when the universe became transparent. Measurements of this background, galaxy redshifts, and light-element abundances support the model and constrain its history."],
"olbers-paradox":["In a static universe that had existed forever with stars spread everywhere, every direction would eventually end on a star and the night sky would be bright. Those assumptions do not describe our universe.","Because the universe has a finite age, light from arbitrarily distant stars has not had time to reach us. Expansion also stretches and dims distant light, so the sky between stars remains dark."],
"stars":["Stars are born in clouds of gas and dust, spend most of their lives fusing hydrogen in their cores, and then evolve according to their mass. Their changing light records changes in temperature, size, and chemical composition.","The Hertzsprung–Russell diagram compares stellar brightness and temperature, revealing groups at different life stages. Spectra and observations of star clusters allow astronomers to test how stars evolve."],
"relativistic-astrophysics":["General relativity predicts that mass and energy curve spacetime, affecting the paths of light and matter. Strong-field environments near compact objects provide especially demanding tests of those predictions.","Astronomers compare precise timing, orbital motion, gravitational lensing, and gravitational-wave signals with relativistic models. Agreement across different observations tests gravity under extreme conditions."],
"solar-system":["The Sun contains most of the system's mass, and its gravity governs the orbits of planets and smaller bodies. The system formed from a rotating cloud of gas and dust about 4.6 billion years ago.","Planetary missions compare worlds at close range, while telescopes and meteorites add evidence about distant objects and early materials. Orbits, surfaces, and compositions help reconstruct the system's formation."],
"high-energy-astrophysics":["At high energies, matter can be heated to millions of degrees or accelerated close to the speed of light. Such conditions occur around compact objects, in supernova remnants, and in powerful galaxy centers.","X-ray and gamma-ray instruments measure energetic photons, while particle detectors and radio telescopes add other clues. Coordinated observations can follow a source from its initial eruption through its changing aftermath."],
"cosmic-ray-astronomy":["Cosmic rays include particles from the Sun as well as much more energetic particles from outside the Solar System. Their paths curve in magnetic fields, which makes identifying their origins difficult.","Detectors measure the particle or the shower of secondary particles it creates in the atmosphere. Combining energy, composition, and arrival direction helps researchers distinguish possible sources and acceleration processes."],
"hubble-constant":["It is commonly expressed in kilometers per second per megaparsec, describing how much faster distant galaxies appear to recede as distance increases. It is a measurement of the expansion rate now, not a speed assigned to every galaxy.","One approach builds a distance ladder from nearby objects; another infers the expansion history from the cosmic microwave background and a cosmological model. The disagreement between some measurements is known as the Hubble tension and is actively studied."]
};
ASTRO_TOPICS.forEach(function(topic){var existing=LESSONS.filter(function(l){return l.id===topic[0]})[0],entry=existing||{id:topic[0],min:6,xp:20,sk:"sci",lv:"Cadet"},expansion=ASTRO_EXPANSIONS[topic[0]]||["Its properties help astronomers connect observations to the larger history and structure of the universe.","By comparing repeated observations with physical models, researchers test explanations and identify questions that need better measurements."];entry.t=topic[1];entry.cat="Astronomy";entry.body=topic[2];entry.details=[["What it is",topic[3]+" "+expansion[0]],["How it is studied",topic[4]+" "+expansion[1]]];if(!existing)LESSONS.push(entry)});
["astro-history","moon-phases","distance-stars","spectra"].forEach(function(id){var entry=LESSONS.filter(function(l){return l.id===id})[0];if(entry)entry.cat="Astronomy"});
var PHYSICS_EXPANSIONS={
"entanglement":["Its correlations belong to the joint quantum state, not to a controllable signal sent between the particles.",["The particles may be carried far apart, yet their shared state still predicts correlated measurement results. The preparation of the pair and later measurements make that relationship observable.","The measurement setting matters: asking about spin along different directions gives different probability patterns. Quantum theory predicts those probabilities, not a guaranteed result for an individual trial.","The effect appears in the statistics collected over many pairs, not in one dramatic measurement. Carefully chosen measurement settings are needed to compare quantum predictions with classical limits.","Bell's result turns a philosophical question into an experiment: measure correlations and compare them with a mathematical bound. Modern tests have closed important loopholes in those comparisons.","Individual outcomes remain unpredictable, so neither observer can choose a result to transmit. The correlation becomes visible only after they compare their records through ordinary communication.","Photons can be entangled using optical processes, while trapped atoms and ions can be linked through controlled interactions. Each platform has different strengths in distance, stability, and control.","Quantum networks aim to distribute entanglement between nodes, and quantum computers use it within designed operations. Loss and decoherence remain practical obstacles.","These terms name mathematical descriptions and experimental tests; they do not describe hidden miniature objects or faster-than-light messages."]],
"superconductivity":["The transition occurs below a material-specific critical temperature and can be lost if the magnetic field or current becomes too large.",["A persistent current can flow without ordinary resistive energy loss. The Meissner effect, in which magnetic fields are expelled, distinguishes superconductivity from a simple perfect conductor.","Strong superconducting magnets are useful when a large, stable field is needed. Cooling equipment is essential because the material must remain below its critical temperature.","Researchers investigate both the microscopic mechanisms and practical limits of each material. Higher operating temperature does not automatically mean an easy-to-build wire or device."]],
"gravitational-waves":["Their detection opened a new way to observe the universe, alongside light and particles such as neutrinos.",["As a wave passes, one direction is stretched while the perpendicular direction is squeezed, then the pattern reverses. The change is extremely small, so instruments need exceptional stability and noise control.","LIGO compares laser light traveling along two long arms. Seismic motion, thermal effects, and instrument noise must be separated from the signal expected from an astrophysical source.","The signal rises in frequency and strength as orbiting objects lose energy and draw closer. Comparing it with theoretical waveforms helps identify whether the source involved black holes or neutron stars.","Gravitational waves carry information about mass and motion that can be difficult to obtain from light alone. If an event also emits light, combining both observations gives a fuller picture."]],
"thermodynamics":["The laws apply at many scales, from engines and refrigerators to stars, spacecraft, and planetary atmospheres.",["A complete energy account includes transfers into and out of a system. This conservation principle is the first law of thermodynamics.","Entropy describes how energy is distributed among microscopic possibilities. It helps explain why many everyday processes have a preferred direction even though energy is conserved.","Temperature predicts the direction heat will flow when systems interact. Absolute zero is a limit that physical processes can approach but cannot reach exactly.","Spacecraft absorb sunlight and generate internal heat, but have little surrounding air to carry it away. Radiators must emit heat to space while heaters and insulation protect sensitive equipment."]],
"string-theory":["The strings proposed by the mathematics are far too small to resolve with current experiments, and versions of the theory require additional structure.",["The proposal is that different vibration patterns would appear as particles with different properties. This is a theoretical framework, not a directly observed picture of particles.","A consistent quantum description of gravity is difficult to build, so string theory is one of several approaches under study. Its mathematical connections have also influenced other areas of theoretical physics.","A framework must ultimately connect to observations. Finding distinctive, testable predictions remains a central challenge for string theory."]],
"quantum-computing":["Quantum effects may help with some carefully chosen algorithms, but they do not make every calculation faster or replace ordinary computers for everyday tasks.",["A qubit is described by amplitudes that determine measurement probabilities. Entanglement can link qubits, while gates change their states in controlled ways.","Measurement produces classical outcomes, so algorithms use interference to make useful results more likely. Repeated runs may be needed because individual outcomes can be probabilistic.","Errors accumulate as qubits interact with their environment. Researchers are improving hardware, error correction, and algorithms to make reliable computations possible."]],
"neutrino-physics":["They carry no electric charge and interact mainly through the weak nuclear force and gravity, so enormous numbers pass through matter unnoticed.",["Flavor changes during flight because neutrinos of different masses contribute to the traveling state. Oscillation experiments measure how often one flavor is detected as another.","Reactors, the Sun, cosmic-ray interactions, and accelerators provide different neutrino sources. Comparing them tests how neutrinos behave across energies and distances.","Their tiny masses and possible differences between neutrinos and antineutrinos may reveal limits of current particle models. Experiments measure these properties with large, carefully shielded detectors."]]
};
LESSONS.forEach(function(entry){var expansion=PHYSICS_EXPANSIONS[entry.id];if(!expansion)return;entry.body+=" "+expansion[0];entry.details=(entry.details||[]).map(function(detail,index){return[detail[0],detail[1]+" "+(expansion[1][index]||"")]})});
var BIOLOGY_TOPICS=[
{id:"cell-biology",t:"Cell biology",min:7,xp:25,sk:"sci",lv:"Cadet",body:"Cell biology explores the structures and activities shared by living cells. Cells take in materials, use energy, respond to signals, and make the molecules needed to grow and reproduce.",details:[["Inside a cell","The cell membrane controls what enters and leaves. Cytoplasm holds many of the cell's working structures, while DNA stores instructions used to build proteins. Plant cells also have structures such as chloroplasts, which capture light energy, and a cell wall for support."],["How scientists study cells","Microscopes reveal cells and some of their structures. Researchers also use stains, fluorescent markers, and molecular tools to follow particular molecules or observe how cells respond to changes. Comparing many cells helps distinguish a general pattern from an unusual sample."]] },
{id:"genetics",t:"Genetics",min:8,xp:25,sk:"sci",lv:"Cadet",body:"Genetics studies genes, DNA, and how biological information is passed from parents to offspring. Genes influence traits through their effects on molecules and development, while environment and chance also shape many characteristics.",details:[["DNA, genes, and chromosomes","DNA is a molecule that stores hereditary information. A gene is a stretch of DNA that contributes to a functional product, often a protein or RNA molecule. DNA is packaged into chromosomes, and people inherit combinations of genetic variants from their biological parents."],["Inheritance and variation","Some traits follow simple inheritance patterns, but many depend on many genes and environmental influences. Mutations and recombination create genetic variation. Geneticists compare DNA and study pedigrees or populations to understand how variants are inherited and how they relate to traits."]] },
{id:"evolutionary-biology",t:"Evolutionary biology",min:8,xp:25,sk:"sci",lv:"Cadet",body:"Evolutionary biology explains how populations change across generations. Inherited variation, mutation, natural selection, genetic drift, and migration all contribute to the patterns of life seen today.",details:[["Change in populations","Individuals within a population vary, and some of that variation is inherited. If a heritable feature affects survival or reproduction in a particular setting, its frequency may change over generations. Natural selection is one mechanism of evolution, alongside mutation, drift, and gene flow."],["Evidence and tree of life","Fossils, anatomy, DNA comparisons, and observations of living populations provide evidence about evolutionary history. Scientists organize relationships into branching trees that represent shared ancestry. Evolution does not mean that every species becomes more complex or progresses toward a fixed goal."]] },
{id:"ecology",t:"Ecology",min:7,xp:25,sk:"sci",lv:"Cadet",body:"Ecology studies how organisms interact with one another and with their physical surroundings. It connects individual behavior to populations, communities, ecosystems, and the movement of energy and materials.",details:[["Relationships in ecosystems","Organisms compete, cooperate, eat, host, and depend on one another in many ways. Producers capture energy, consumers obtain it by feeding, and decomposers recycle nutrients. Temperature, water, soil, and light also shape which organisms can live in a place."],["Measuring ecological change","Ecologists survey species, track populations, run field experiments, and use models to understand patterns. Long-term observations can show how habitats respond to climate, disturbance, or human activity. Results depend on where and when measurements are taken, so sampling methods matter."]] },
{id:"physiology",t:"Physiology",min:7,xp:25,sk:"sci",lv:"Cadet",body:"Physiology examines how living bodies and their parts work. It links cells, tissues, organs, and whole-body systems to processes such as movement, digestion, gas exchange, and water balance.",details:[["Systems working together","Body functions rely on coordinated systems. For example, breathing brings oxygen into the lungs, circulation transports it, and cells use it in energy-releasing reactions. Plants also have physiology: roots take up water, leaves exchange gases, and vascular tissues move water and sugars."],["Regulation and response","Organisms regulate internal conditions as their surroundings change. Feedback mechanisms can adjust temperature, blood chemistry, or water balance. Physiologists investigate these processes by measuring how a system responds to a controlled change, while considering that species and individuals can differ."]] },
{id:"microbiology",t:"Microbiology",min:7,xp:25,sk:"sci",lv:"Cadet",body:"Microbiology studies microscopic life, including bacteria, archaea, many fungi, and microscopic algae and protists. These organisms are diverse: some cause disease, while many support ecosystems, digestion, food production, and nutrient cycles.",details:[["A microscopic world","Bacteria and archaea are single-celled organisms without a nucleus. Fungi include yeasts and microscopic molds, and protists include many varied eukaryotes. Viruses are also studied in microbiology, though they are not cells and depend on host cells to reproduce."],["Methods and roles","Microscopes, cell culture, DNA sequencing, and biochemical tests help identify microbes and study what they do. Microbes break down organic matter, transform nutrients, and live in communities with plants and animals. Careful sterile technique helps researchers tell a real result from contamination."]] },
{id:"biochemistry",t:"Biochemistry",min:8,xp:25,sk:"sci",lv:"Cadet",body:"Biochemistry investigates the molecules and chemical reactions that make life possible. It studies how cells obtain and use energy, build structures, copy information, and regulate their activities.",details:[["Molecules of life","Proteins perform many structural and catalytic roles; carbohydrates store energy and help form structures; lipids make membranes and store energy; and nucleic acids carry genetic information. The shape and chemical properties of these molecules influence how they interact."],["Reactions and energy","Metabolic pathways are linked sequences of chemical reactions. Enzymes help reactions occur at useful rates, while cells manage energy transfers using molecules such as ATP. Biochemists measure molecules and reaction rates to understand how pathways are controlled and how they change under different conditions."]] },
{id:"botany",t:"Botany",min:7,xp:25,sk:"sci",lv:"Cadet",body:"Botany is the study of plants, from mosses and ferns to flowering plants and trees. Botanists investigate plant structure, growth, reproduction, diversity, and relationships with the environment.",details:[["How plants live","Plants capture light through photosynthesis, exchange gases, and move water and sugars through specialized tissues. Roots anchor plants and absorb water and minerals; leaves often capture light; flowers and cones are involved in reproduction for different plant groups."],["Plant diversity and research","Botanists classify plants, examine fossils, study plant genetics, and monitor how species respond to conditions such as drought or changing temperatures. Herbarium collections preserve labeled plant specimens that allow researchers to compare species and changes over time."]] },
{id:"zoology",t:"Zoology",min:7,xp:25,sk:"sci",lv:"Cadet",body:"Zoology studies animals: their bodies, behavior, development, classification, and evolution. It spans microscopic animals to large mammals and considers how animal life fits into ecosystems.",details:[["Animal structure and behavior","Animals have adaptations for obtaining food, sensing their surroundings, moving, and reproducing. Zoologists compare anatomy and behavior across species to understand how these features function and how they may have evolved."],["Studying animals responsibly","Researchers observe animals in the wild, examine museum specimens, and conduct carefully designed studies. Population surveys and tracking can reveal migration and habitat use. Ethical research minimizes harm and considers the welfare of individual animals as well as conservation needs."]] },
{id:"immunology",t:"Immunology",min:8,xp:25,sk:"sci",lv:"Cadet",body:"Immunology studies the body's defenses and how immune cells and molecules recognize and respond to potential threats. The immune system also helps clear damaged cells and must regulate its responses to avoid unnecessary harm.",details:[["Layers of defense","Physical barriers such as skin and mucous membranes help keep many microbes out. Innate immune responses act quickly, while adaptive responses involve specialized B and T cells. Some adaptive cells can persist after an infection or vaccination and respond more quickly if they encounter a familiar target again."],["Recognition and balance","Immune cells use receptors and signaling molecules to coordinate responses. A successful defense must identify targets while limiting damage to the body's own tissues. Immunologists study these interactions in cells, model organisms, and clinical research; this overview is educational and not personal medical guidance."]] },
{id:"neuroscience",t:"Neuroscience",min:8,xp:25,sk:"sci",lv:"Cadet",body:"Neuroscience explores the nervous system, including the brain, spinal cord, and nerves. It studies how nerve cells communicate and how networks support sensation, movement, learning, memory, and other behaviors.",details:[["Neurons and networks","Neurons receive and send electrical signals, and many communicate across synapses using chemical messengers. Support cells help maintain the environment around neurons and contribute to nervous-system function. Groups of connected cells form circuits that process information."],["Studying the nervous system","Neuroscientists combine observations of behavior with methods such as microscopy, electrical recording, imaging, and computational models. Each method measures different aspects of nervous-system activity, and no single brain image explains a person's thoughts or behavior by itself."]] },
{id:"marine-biology",t:"Marine biology",min:7,xp:25,sk:"sci",lv:"Cadet",body:"Marine biology studies organisms and ecosystems in oceans and other saltwater environments. It includes microscopic plankton, coral communities, open-ocean animals, and life around deep-sea vents.",details:[["Life in the ocean","Ocean conditions vary with depth, temperature, light, pressure, and nutrients. Phytoplankton capture sunlight near the surface and support many food webs, while deep-sea communities can rely on sinking organic matter or chemical energy from the seafloor."],["Observation and conservation","Marine biologists use ships, underwater instruments, remote cameras, genetic sampling, and satellite data to study ocean life. Surveys help track populations and habitats, while long-term measurements reveal effects of warming, pollution, fishing, and other changes. The ocean is vast, so observations often cover only part of an ecosystem."]] },
{id:"pathology",t:"Pathology",min:8,xp:25,sk:"sci",lv:"Cadet",body:"Pathology studies disease and the changes it causes in cells, tissues, and organs. It helps connect biological mechanisms with evidence from samples and observations.",details:[["From cells to disease","Disease can alter how cells grow, communicate, or perform their normal roles. Pathologists examine tissues, cells, and other specimens to identify patterns such as inflammation, infection, or abnormal growth. A finding must be interpreted alongside its context and other evidence."],["How pathology is used","Methods can include microscopy, laboratory chemistry, molecular testing, and examination of tissue structure. These approaches support research and clinical diagnosis, but a test result is not meaningful without appropriate interpretation by qualified professionals."]] },
{id:"biotechnology",t:"Biotechnology",min:8,xp:25,sk:"sci",lv:"Cadet",body:"Biotechnology uses organisms, cells, or biological molecules to develop tools and products. Examples range from fermentation and crop improvement to diagnostic tests and medicines made using engineered cells.",details:[["Working with biological systems","Biotechnologists may use microbes to make useful substances, enzymes in manufacturing, or cells to produce a protein. Modern methods can change or read DNA, but a biological system's behavior depends on many interacting factors and must be tested carefully."],["Applications and responsibility","Biotechnology supports agriculture, medicine, environmental monitoring, and research. Developers evaluate whether a product works, how consistently it can be made, and what effects it may have. Safety, access, environmental impact, and informed oversight are part of responsible use."]] }
];
