function makePlayerId(){return window.crypto&&typeof window.crypto.randomUUID==="function"?window.crypto.randomUUID():"player-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2)}
function load(){var d={id:"",name:"",call:"",av:0,avatarImage:"",patch:0,shape:0,spec:"",track:"",consent:false,xp:0,streak:0,last:"",done:[],sk:{nav:0,eng:0,sci:0},claimed:"",supXpDay:"",supXpQuestions:[],inventory:{p:0,w:0,f:0},saved:false};
try{var r=localStorage.getItem("oa");if(r)Object.assign(d,JSON.parse(r))}catch(e){}if(!d.inventory||typeof d.inventory!=="object")d.inventory={};["p","w","f"].forEach(function(k){var n=Number(d.inventory[k]);d.inventory[k]=Number.isFinite(n)?Math.max(0,Math.floor(n)):0});if(typeof d.id!=="string"||!/^[\w-]{10,80}$/.test(d.id))d.id=makePlayerId();d.call=typeof d.call==="string"?d.call.replace(/\s/g,"").slice(0,10):"";if(!Number.isInteger(d.av)||!AVS[d.av])d.av=0;if(!Number.isInteger(d.patch)||!PATCH[d.patch])d.patch=0;if(!Number.isInteger(d.shape)||!SHAPES[d.shape])d.shape=0;if(typeof d.avatarImage!=="string"||d.avatarImage.indexOf("data:image/")!==0)d.avatarImage="";return d}
function playerPayload(){var progress={};["name","call","av","avatarImage","patch","shape","spec","track","consent","xp","streak","last","done","sk","claimed","econ","supXpDay","supXpQuestions","supDay","cr","inventory","testDay","labDay","labDone","solDay","lessonDay","saved"].forEach(function(key){if(S[key]!==undefined)progress[key]=S[key]});progress.colony=colony||null;return{id:S.id,name:S.name||S.call,callsign:S.call,xp:S.xp,progress:progress}}
function syncProgressNow(){if(!S.saved||!S.call||progressRestoring)return Promise.resolve();return fetch("/api/leaderboard",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(playerPayload())}).then(function(response){if(!response.ok)throw new Error("Profile could not be saved (HTTP "+response.status+")");return response})}
function syncProgress(){if(!S.saved||!S.call||progressRestoring)return;clearTimeout(leaderboardSyncTimer);leaderboardSyncTimer=setTimeout(function(){syncProgressNow().catch(function(){})},250)}
function save(){try{localStorage.setItem("oa",JSON.stringify(S))}catch(e){}syncProgress()}
function restoreProgress(){if(!S.saved||!S.call)return;progressRestoring=true;fetch("/api/progress?id="+encodeURIComponent(S.id),{cache:"no-store"}).then(function(response){if(response.status===404)return null;if(!response.ok)throw new Error("Could not load progress");return response.json()}).then(function(data){if(data&&data.progress){Object.assign(S,data.progress);if(data.progress.colony)colony=data.progress.colony;else if(data.progress.colony===null)colony=null;try{localStorage.setItem("oa",JSON.stringify(S))}catch(e){}head();render()}}).catch(function(){/* Keep the local save if the server is unavailable. */}).finally(function(){progressRestoring=false;syncProgress()})}
function $(i){return document.getElementById(i)}
