function toast(m){var t=document.createElement("div");t.className="toast";t.textContent=m;document.body.appendChild(t);setTimeout(function(){t.remove()},2200)}
function gain(x,sk){S.xp+=x;if(sk)S.sk[sk]=(S.sk[sk]||0)+x;var d=new Date().toDateString();if(S.last!==d){var y=new Date(Date.now()-864e5).toDateString();S.streak=S.last===y?S.streak+1:1;S.last=d}save();head()}
function head(){$("me").innerHTML='<button class="header-hub" data-go="hub" aria-label="Open Hub"><span class="header-user"><b>'+esc(S.call||"Unnamed recruit")+'</b><small>'+rank()+' · '+S.xp+' XP · '+(S.cr||0)+' cr</small></span><span class="header-avatar">'+avatarMarkup(30)+'</span></button>'}
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function avatarMarkup(size){return S.avatarImage?'<img class="avatar-img" src="'+S.avatarImage+'" alt="Selected avatar" style="width:'+size+'px;height:'+size+'px">':'<span style="font-size:'+size+'px">'+(AVS[S.av]||AVS[0])+'</span>'}
var TABS=[["dash","🌌","Base"],["hub","🧑‍🚀","Hub"],["ctl","📡","Control"],["acad","📚","Library"],["col","🌱","Colony"],["lab","🛰️","Lab"],["test","✅","Tests"],["rank","🏅","Rank"]];
