function labv(){
if(!lab)return'<div class="card"><h1 style="font-size:26px">Mission Lab: Mars transfer</h1><p class="mut">Cover 100 units of distance without running out of fuel or oxygen. Each day you pick a burn profile. Watch for events.</p><button class="btn" data-act="lstart">Launch simulation</button></div>';
function g(n,v,c){return'<div class="gauge"><span>'+n+' '+Math.max(0,v)+'</span><div class="bar"><i style="width:'+Math.max(0,Math.min(100,v))+'%;background:'+c+'"></i></div></div>'}
var h='<div class="card"><h2>Day '+lab.day+'</h2>'+g("Distance",lab.d,"var(--cy)")+g("Fuel",lab.f,"var(--am)")+g("Oxygen",lab.o,"var(--ok)")+'<p class="mut">'+esc(lab.msg)+'</p>';
if(lab.over)return h+'<h3>'+(lab.win?"Mars orbit achieved! +40 XP":"Mission failed: "+lab.why)+'</h3><button class="btn" data-act="lstart">Try again</button></div>';
if(lab.ev)return h+'<h3>Solar flare warning</h3><button class="opt" data-lev="shelter">Shelter in the storm cellar (−12 oxygen, safe)</button><button class="opt" data-lev="push">Push through (50% chance of −25 fuel from damage)</button></div>';
return h+'<button class="opt" data-lm="cruise">Cruise: +10 distance, −8 fuel, −10 oxygen</button><button class="opt" data-lm="boost">Boost: +18 distance, −16 fuel, −10 oxygen</button><button class="opt" data-lm="save">Conserve: +5 distance, −3 fuel, −6 oxygen</button></div>'}
function lStep(m){var L=lab;var t={cruise:[10,8,10],boost:[18,16,10],save:[5,3,6]}[m];L.d+=t[0];L.f-=t[1];L.o-=t[2];L.day++;L.msg="Day complete.";
if(L.day>4&&Math.random()<.2){L.o-=10;L.msg="Micrometeoroid hit: a small leak cost 10 oxygen."}
lEnd();if(!L.over&&!L.flare&&L.d>=45){L.flare=true;L.ev=true;L.msg="Alert from mission control."}render()}
function lEnd(){var L=lab;if(L.f<0||L.o<0){L.over=true;L.why=L.o<0?"crew ran out of oxygen.":"ship ran out of fuel.";gain(5,"eng")}else if(L.d>=100){L.over=true;L.win=true;gain(40,"nav");gain(0,"eng")}else if(L.day>30){L.over=true;L.why="the transfer window closed."}}
