function buySup(k){var C=colony,b={p:30,w:25,f:25}[k];if(!b)return;var lv=C&&!C.over?Math.max(0,Math.min(100,C[k])):100,pr=Math.round(b*(1+(100-lv)/100));if((S.cr||0)<pr)return;S.inventory=S.inventory||{p:0,w:0,f:0};S.inventory[k]=(S.inventory[k]||0)+1;S.cr-=pr;save();toast('Added '+{p:'power cell',w:'water tank',f:'ration pack'}[k]+' to your inventory');render()}
function useSup(k){var C=colony;if(!C||C.over||!S.inventory||!S.inventory[k]||C[k]>=100)return;S.inventory[k]--;C[k]=Math.min(100,C[k]+20);save();toast('Used '+{p:'power cell',w:'water tank',f:'ration pack'}[k]+' · +20 '+{p:'power',w:'water',f:'food'}[k]);render()}
