if(low){C.over=true;C.why="the colony ran out of "+low+".";gain(10,"surv")}
else if(C.sol>30){C.over=true;C.win=true;C.sol=30;gain(50+20*P.lv,"surv")}
else if(C.p<20||C.w<20||C.f<20)msg+=" Warning: a supply is below 20.";
